-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;
SET allow_suspicious_variant_types = 1;

-- An explicit Variant schema over an ORC union can use all the integer targets the ordinary
-- (non-union) column path supports through the final cast: the unsigned and Enum types of the
-- matching width. The branch is hinted and cast before the Variant is assembled, because
-- Variant -> Variant conversion cannot change the nested types afterwards.

-- union<int32, string> read as Variant(UInt32, String). Rows: 10, 'x', 30, 'z'.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(UInt32, String)', unhex('')) ORDER BY toString(u);

-- union<tinyint, string> with a null tinyint payload, read as Variant(Enum8, String) and as
-- Variant(UInt8, String). The enum has no value 0, so the cast must not inspect the placeholder
-- at the null-payload position (that row is a Variant NULL). Rows: 5, 'a', NULL, 7.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Enum8(\'lo\' = 5, \'hi\' = 7), String)', unhex('')) ORDER BY toString(u);
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(UInt8, String)', unhex('')) ORDER BY toString(u);

-- union<smallint, bigint> read as Variant(Enum16, UInt64). Rows: 300, 70000.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Enum16(\'e300\' = 300), UInt64)', unhex('')) ORDER BY toString(u);

-- The integer targets also apply to nested leaves of complex branches.
-- union<list<int32>, string> read as Variant(Array(UInt32), String). Rows: [1,2], 'a', [3].
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Array(UInt32), String)', unhex('')) ORDER BY toString(u);

-- union<map<string,tinyint>, int32> read as Variant(Int32, Map(String, Enum8)). Rows: {'k':5}, 42.
SELECT u, toTypeName(u) FROM format(ORC, 'u Variant(Int32, Map(String, Enum8(\'lo\' = 5)))', unhex('')) ORDER BY toString(u);
